  (forall a, 0 <= a < 2 ^ 64 -> wview asegs m (wa a) <> None -> wview asegs m' (wa a) <> None) ->
  (forall a, sh AIMG_LO <= a < sh AIMG_TOP -> exists b, mrd asegs m' (wa a) = Some b) ->
  ACONST m'.
